CREATE DATABASE IF NOT EXISTS tt_viet_cafe CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci; USE tt_viet_cafe;
CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(50) UNIQUE NOT NULL,password VARCHAR(100) NOT NULL,full_name VARCHAR(100),role VARCHAR(30) DEFAULT 'cashier');
CREATE TABLE IF NOT EXISTS categories(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS products(id INT AUTO_INCREMENT PRIMARY KEY,category_id INT NOT NULL,name VARCHAR(150) NOT NULL,price DECIMAL(12,2) NOT NULL,active TINYINT DEFAULT 1,FOREIGN KEY(category_id) REFERENCES categories(id));
CREATE TABLE IF NOT EXISTS cafe_tables(id INT AUTO_INCREMENT PRIMARY KEY,table_name VARCHAR(30) UNIQUE NOT NULL,status VARCHAR(20) DEFAULT 'Trống');
CREATE TABLE IF NOT EXISTS orders(id BIGINT AUTO_INCREMENT PRIMARY KEY,order_code VARCHAR(30) UNIQUE NOT NULL,table_id INT NULL,user_id INT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,total DECIMAL(12,2) DEFAULT 0,status VARCHAR(20) DEFAULT 'Đã thanh toán',FOREIGN KEY(table_id) REFERENCES cafe_tables(id),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS order_details(id BIGINT AUTO_INCREMENT PRIMARY KEY,order_id BIGINT NOT NULL,product_id INT NOT NULL,quantity INT NOT NULL,unit_price DECIMAL(12,2) NOT NULL,line_total DECIMAL(12,2) NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(product_id) REFERENCES products(id));
